html:
{% set budget_rows = doc.budget_rows or [] %}
{% set part_budgets = doc.part_budgets or [] %}
{% set kit_rates = doc.kit_rates %}
{% set pl = doc.profit_loss or 0 %}

<style>
  .xf-pl-header { background: #0f1d42; color: #fff; padding: 16px 20px; margin: -8px -8px 16px; }
  .xf-pl-header h1 { margin: 0; font-size: 22px; }
  .xf-pl-header .sub { font-size: 10px; color: #96a8d0; margin-top: 4px; }
  .xf-pl-meta { font-size: 10px; color: #646e8a; margin-bottom: 12px; }
  .xf-pl-kpi { display: table; width: 100%; margin-bottom: 16px; }
  .xf-pl-kpi .card { display: table-cell; background: #f0f3fc; padding: 10px; border: 1px solid #dde0ec; }
  .xf-pl-kpi .lbl { font-size: 8px; color: #7a8194; text-transform: uppercase; }
  .xf-pl-kpi .val { font-size: 13px; font-weight: bold; }
  .xf-pl-table { width: 100%; border-collapse: collapse; font-size: 10px; margin-bottom: 16px; }
  .xf-pl-table th { background: #1a3a8f; color: #fff; padding: 6px 8px; text-align: left; }
  .xf-pl-table td { padding: 6px 8px; border-bottom: 1px solid #eef0f6; }
  .xf-pl-table .num { text-align: right; }
  .xf-pl-table .total td { background: #e8edf8; font-weight: bold; }
  .xf-pl-part-title { font-size: 11px; margin: 14px 0 6px; color: #0f1d42; }
  .xf-pl-banner { padding: 12px 16px; border-radius: 6px; margin-top: 12px; }
  .xf-pl-banner.profit { background: #e7f4ed; border: 1px solid #b8ddc7; color: #1e6b3a; }
  .xf-pl-banner.loss { background: #fcecea; border: 1px solid #f0bcbc; color: #a0231c; }
  .xf-pl-banner .big { font-size: 18px; font-weight: bold; float: right; }
  .xf-pl-footer { font-size: 8px; color: #b0b7c6; margin-top: 20px; border-top: 1px solid #dde0ec; padding-top: 8px; }
</style>

<div class="xf-pl-header">
  <table width="100%"><tr>
    <td><h1>Xfloor</h1><div class="sub">Project P&amp;L Report</div></td>
    <td style="text-align:right;vertical-align:top">
      <div>{{ doc.project_number or doc.name }}</div>
      <div class="sub">Generated: {{ frappe.utils.formatdate(frappe.utils.nowdate(), "dd MMM yyyy") }}</div>
      {% if kit_rates.rates_effective_date %}<div class="sub">Kit rates as of: {{ frappe.utils.formatdate(kit_rates.rates_effective_date, "dd MMM yyyy") }}</div>{% endif %}
    </td>
  </tr></table>
</div>

<h3 style="margin:0 0 4px">{{ doc.party_name or "Unnamed project" }}</h3>
<div class="xf-pl-meta">
  {{ (doc.sqft or 0)|int }} sq ft &middot; ₹{{ doc.rate_per_sqft or 0 }}/sqft
  {% if part_budgets %}
    &middot; {{ part_budgets|length }} part{{ "s" if part_budgets|length != 1 else "" }}
  {% else %}
    &middot; Top coat: {{ doc.top_coat_option or "1mm" }} &middot; Screed: {{ doc.screed_option or "1mm" }}
  {% endif %}
</div>

<div class="xf-pl-kpi">
  <div class="card"><div class="lbl">Contract Value</div><div class="val">{{ frappe.utils.fmt_money(doc.contract_value or 0, currency="INR") }}</div></div>
  <div class="card"><div class="lbl">Total Cost</div><div class="val">{{ frappe.utils.fmt_money(doc.total_cost or 0, currency="INR") }}</div></div>
  <div class="card"><div class="lbl">Cost/sqft</div><div class="val">₹{{ "%.2f"|format(doc.cost_per_sqft or 0) }}</div></div>
  <div class="card"><div class="lbl">Margin</div><div class="val">{{ "%.1f"|format(doc.margin_pct or 0) }}%</div></div>
</div>

{% macro budget_table(rows, sqft, total_cost, cost_per_sqft) %}
<table class="xf-pl-table">
  <thead><tr>
    <th>Component</th><th>Option</th><th class="num">Sqft/kit</th>
    <th class="num">Kits</th><th class="num">Rate/kit</th><th class="num">Cost</th><th class="num">Cost/sqft</th>
  </tr></thead>
  <tbody>
    {% for row in rows %}
    <tr>
      <td><b>{{ row.component }}</b></td>
      <td>{{ row.option or "—" }}</td>
      <td class="num">{% if row.coverage %}{{ (row.coverage or 0)|int }}{% else %}—{% endif %}</td>
      <td class="num">{% if row.component != "Applicator" %}{{ (row.kits or 0)|int }}{% else %}—{% endif %}</td>
      <td class="num">{% if row.component == "Applicator" and row.rate %}₹{{ "%.2f"|format(row.rate) }}/sqft{% else %}{{ frappe.utils.fmt_money(row.rate or 0, currency="INR") }}{% endif %}</td>
      <td class="num">{{ frappe.utils.fmt_money(row.cost or 0, currency="INR") }}</td>
      <td class="num">{% if sqft %}₹{{ "%.2f"|format(row.cost_per_sqft or 0) }}{% else %}—{% endif %}</td>
    </tr>
    {% endfor %}
    <tr class="total">
      <td colspan="5" class="num">Total</td>
      <td class="num">{{ frappe.utils.fmt_money(total_cost or 0, currency="INR") }}</td>
      <td class="num">₹{{ "%.2f"|format(cost_per_sqft or 0) }}</td>
    </tr>
  </tbody>
</table>
{% endmacro %}

{% for part in part_budgets %}
  <div class="xf-pl-part-title">{{ part.part_name }} &middot; {{ (part.sqft or 0)|int }} sq ft</div>
  {{ budget_table(part.budget_rows or [], part.sqft, (part.summary or {}).total_cost, (part.summary or {}).cost_per_sqft) }}
{% endfor %}

<h4 style="margin:8px 0;font-size:11px">Project Total</h4>
{{ budget_table(budget_rows, doc.sqft, doc.total_cost, doc.cost_per_sqft) }}

<div class="xf-pl-banner {{ "profit" if pl >= 0 else "loss" }}">
  <span class="big">{{ "+" if pl >= 0 else "" }}{{ frappe.utils.fmt_money(pl, currency="INR") }}</span>
  <b>{{ "PROFIT" if pl >= 0 else "LOSS" }}</b><br>
  <span style="font-size:10px">{{ frappe.utils.fmt_money(doc.contract_value or 0, currency="INR") }} contract − {{ frappe.utils.fmt_money(doc.total_cost or 0, currency="INR") }} total cost</span>
</div>

<div class="xf-pl-footer">Xfloor Project Manager &mdash; Confidential</div>
